const cmds = [
  ["ps", "ps -eo pid,ppid,stat,etime,%cpu,%mem,cmd --sort=-%cpu | head -n 40", "."],
  ["resources", "free -h; getconf _NPROCESSORS_ONLN; nvidia-smi --query-gpu=index,name,memory.total,memory.used,utilization.gpu --format=csv,noheader", "."],
  ["artifact", "stat -c '%n|%s bytes|%y' /tmp/v3_robust.csv; wc -l /tmp/v3_robust.csv; head -n 3 /tmp/v3_robust.csv | cut -c1-240; tail -n 2 /tmp/v3_robust.csv | cut -c1-240", "."],
];
const results = await Promise.all(cmds.map(async ([name, cmd, workdir]) => {
  const r = await tools.exec_command({cmd, workdir, yield_time_ms: 10000, max_output_tokens: 5000});
  return {name, ...r};
}));
for (const r of results) {
  text(`--- ${r.name} exit=${r.exit_code} ---\n${r.output}`);
}

const calls = [
  tools.exec_command({
    cmd: "ps -p 3076049,3027982 -o pid,ppid,stat,etime,%cpu,%mem,args; for p in 3076049 3027982; do if [ -d /proc/$p ]; then readlink /proc/$p/cwd; tr '\\0' ' ' < /proc/$p/cmdline; printf '\\n'; fi; done",
    workdir: ".",
    yield_time_ms: 10000,
    max_output_tokens: 4000
  }),
  tools.exec_command({
    cmd: "rg -n \"encode|decode|submission.csv|delta_a|delta_b|zlib|base64|torch.save|numpy\" submission/script.py official input candidates -g '*.py' -g '*.md' | head -n 160",
    workdir: ".",
    yield_time_ms: 10000,
    max_output_tokens: 8000
  }),
  tools.exec_command({
    cmd: "nvidia-smi 2>&1 | head -n 80; /opt/conda/envs/ioai/bin/python - <<'PY'\nimport torch\nprint('torch_cuda_available', torch.cuda.is_available())\nprint('torch_cuda_count', torch.cuda.device_count())\nfor i in range(torch.cuda.device_count()):\n    print(i, torch.cuda.get_device_name(i), torch.cuda.mem_get_info(i))\nPY",
    workdir: ".",
    yield_time_ms: 10000,
    max_output_tokens: 5000
  })
];
const rs = await Promise.all(calls);
for (let i=0;i<rs.length;i++) text(`--- check${i+1} exit=${rs[i].exit_code} ---\n${rs[i].output}`);

const rs = await Promise.all([
  tools.exec_command({
    cmd: "command -v python; python - <<'PY'\nimport sys\nprint(sys.executable)\ntry:\n import torch\n print('torch', torch.__version__, 'cuda', torch.cuda.is_available(), 'count', torch.cuda.device_count())\n for i in range(torch.cuda.device_count()):\n  print(i, torch.cuda.get_device_name(i), torch.cuda.mem_get_info(i))\nexcept Exception as e:\n print(type(e).__name__, str(e))\nPY",
    workdir: ".",
    yield_time_ms: 10000,
    max_output_tokens: 3000
  }),
  tools.exec_command({
    cmd: "rg --files input/competition | rg 'test_leaderboard_[ab]/images/[0-9]+\\.png$' | head -n 12; rg --files input/competition | rg 'test_leaderboard_[ab]/images/[0-9]+\\.png$' | wc -l",
    workdir: ".",
    yield_time_ms: 10000,
    max_output_tokens: 3000
  }),
  tools.exec_command({
    cmd: "ps -p 3076049,3027982 -o pid,ppid,stat,etime,%cpu,%mem,args",
    workdir: ".",
    yield_time_ms: 10000,
    max_output_tokens: 2000
  })
]);
for (let i=0;i<rs.length;i++) text(`--- result${i+1} exit=${rs[i].exit_code} ---\n${rs[i].output}`);

const rs = await Promise.all([
  tools.exec_command({
    cmd: "ps -p 3076047,3076049,3027978,3027982 -o pid,ppid,user,stat,etime,%cpu,%mem,args; for p in 3076047 3076049 3027978 3027982; do if [ -d /proc/$p ]; then printf 'PID %s cwd=' \"$p\"; readlink /proc/$p/cwd || true; printf 'PID %s stdout=' \"$p\"; readlink /proc/$p/fd/1 || true; fi; done",
    workdir: ".",
    yield_time_ms: 10000,
    max_output_tokens: 4000
  }),
  tools.exec_command({
    cmd: "sed -n '1,260p' /tmp/runtime_v2_replay.py",
    workdir: ".",
    yield_time_ms: 10000,
    max_output_tokens: 12000
  }),
  tools.exec_command({
    cmd: "ls -lh /tmp/runtime_v2_replay.py /tmp/v3_robust.csv; find /tmp -maxdepth 2 -type f -mmin -10 -printf '%TY-%Tm-%Td %TH:%TM:%TS %s %p\\n' 2>/dev/null | sort -r | head -n 40",
    workdir: ".",
    yield_time_ms: 10000,
    max_output_tokens: 5000
  })
]);
for (let i=0;i<rs.length;i++) text(`--- result${i+1} exit=${rs[i].exit_code} ---\n${rs[i].output}`);

const rs = await Promise.all([
  tools.exec_command({
    cmd: "tail -n 15 records/experiments.jsonl",
    workdir: ".",
    yield_time_ms: 10000,
    max_output_tokens: 8000
  }),
  tools.exec_command({
    cmd: "for f in /tmp/checkv3.log /tmp/checkv3_light.log /tmp/checkv3_fixed.log; do printf '%s\\n' \"$f\"; sed -n '1,120p' \"$f\" 2>/dev/null; done",
    workdir: ".",
    yield_time_ms: 10000,
    max_output_tokens: 5000
  }),
  tools.exec_command({
    cmd: "find /tmp -maxdepth 1 -type f \\( -iname '*v3*' -o -iname '*robust*' -o -iname '*runtime*' \\) -printf '%TY-%Tm-%Td %TH:%TM:%TS %s %p\\n' | sort",
    workdir: ".",
    yield_time_ms: 10000,
    max_output_tokens: 5000
  })
]);
for (let i=0;i<rs.length;i++) text(`--- result${i+1} exit=${rs[i].exit_code} ---\n${rs[i].output}`);

